import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface LayoutProps {
    children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
    const [isMenuOpen, setIsMenuOpen] = useState(false);

    const toggleMenu = () => setIsMenuOpen(!isMenuOpen);

    const menuVariants = {
        closed: { opacity: 0, x: "100%" },
        open: { opacity: 1, x: 0 },
    };

    return (
        <div className="min-h-screen bg-white">
            {/* Navigation */}
            <motion.nav
                initial={{ y: -100, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ duration: 0.5 }}
                className="fixed top-0 left-0 right-0 z-50 glass-nav"
            >
                <div className="max-w-container mx-auto px-6 py-4 flex items-center justify-between">
                    <motion.a
                        href="#"
                        whileHover={{ scale: 1.05 }}
                        className="text-2xl font-heading font-bold text-slate-900 z-50 relative"
                    >
                        EA David
                    </motion.a>

                    {/* Desktop Menu */}
                    <div className="hidden md:flex gap-8">
                        {['About', 'Skills', 'Projects', 'Experience', 'Certifications'].map((item, index) => (
                            <motion.a
                                key={item}
                                href={`#${item.toLowerCase()}`}
                                initial={{ opacity: 0, y: -20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.1 + 0.3 }}
                                whileHover={{ y: -2 }}
                                className="text-slate-600 hover:text-accent transition-colors duration-300 font-medium"
                            >
                                {item}
                            </motion.a>
                        ))}
                    </div>

                    {/* Mobile Hamburger Button */}
                    <button
                        className="md:hidden z-50 relative p-2 text-slate-800 focus:outline-none"
                        onClick={toggleMenu}
                        aria-label="Toggle Menu"
                    >
                        <div className={`w-6 h-0.5 bg-current mb-1.5 transition-all duration-300 ${isMenuOpen ? 'rotate-45 translate-y-2' : ''}`}></div>
                        <div className={`w-6 h-0.5 bg-current mb-1.5 transition-all duration-300 ${isMenuOpen ? 'opacity-0' : ''}`}></div>
                        <div className={`w-6 h-0.5 bg-current transition-all duration-300 ${isMenuOpen ? '-rotate-45 -translate-y-2' : ''}`}></div>
                    </button>

                    {/* Mobile Menu Overlay */}
                    <AnimatePresence>
                        {isMenuOpen && (
                            <motion.div
                                initial="closed"
                                animate="open"
                                exit="closed"
                                variants={menuVariants}
                                transition={{ type: "spring", stiffness: 300, damping: 30 }}
                                className="fixed inset-0 bg-white/98 backdrop-blur-xl z-40 flex flex-col items-center justify-center space-y-8"
                            >
                                {['About', 'Skills', 'Projects', 'Experience', 'Certifications'].map((item) => (
                                    <motion.a
                                        key={item}
                                        href={`#${item.toLowerCase()}`}
                                        onClick={() => setIsMenuOpen(false)}
                                        whileHover={{ scale: 1.1, color: '#16a34a' }}
                                        className="text-3xl font-bold text-slate-800 hover:text-accent transition-colors"
                                    >
                                        {item}
                                    </motion.a>
                                ))}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </motion.nav>

            {/* Main Content */}
            <main className="pt-20">
                {children}
            </main>

            {/* Footer */}
            <footer className="border-t border-slate-100 mt-20 bg-slate-50">
                <div className="max-w-container mx-auto px-6 py-12">
                    <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                        <div className="text-slate-600 text-center md:text-left">
                            <p className="font-heading font-bold text-slate-900 mb-2">EA David (Trovost)</p>
                            <p className="text-sm">Frontend Developer | Building exceptional digital experiences</p>
                        </div>

                        <div className="flex gap-6">
                            <motion.a
                                whileHover={{ y: -3, color: '#16a34a' }}
                                href="mailto:ccrowndavid@gmail.com"
                                className="text-slate-500 hover:text-accent transition-colors"
                            >
                                Email
                            </motion.a>
                            <motion.a
                                whileHover={{ y: -3, color: '#16a34a' }}
                                href="tel:+2347087115019"
                                className="text-slate-500 hover:text-accent transition-colors"
                            >
                                Phone
                            </motion.a>
                        </div>
                    </div>

                    <div className="mt-8 pt-8 border-t border-slate-200 text-center text-slate-500 text-sm">
                        <p>© {new Date().getFullYear()} EA David. All rights reserved.</p>
                    </div>
                </div>
            </footer>
        </div>
    );
};

export default Layout;
