import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

if (typeof window !== 'undefined') {
    gsap.registerPlugin(ScrollTrigger);
}

const About: React.FC = () => {
    const sectionRef = useRef<HTMLElement>(null);

    useEffect(() => {
        if (sectionRef.current && typeof window !== 'undefined') {
            const elements = sectionRef.current.querySelectorAll('.animate-on-scroll');

            elements.forEach((element, index) => {
                gsap.fromTo(
                    element,
                    { opacity: 0, y: 50 },
                    {
                        opacity: 1,
                        y: 0,
                        duration: 0.8,
                        delay: index * 0.1,
                        scrollTrigger: {
                            trigger: element,
                            start: 'top 80%',
                            toggleActions: 'play none none reverse',
                        },
                    }
                );
            });
        }
    }, []);

    const softSkills = [
        'Fast learner',
        'Self-starter',
        'Creative/deep thinker',
        'Problem solver',
        'Open-minded and adaptable',
        'Critical thinker',
        'Good communication',
        'Team player',
        'Empathy',
    ];

    return (
        <section id="about" ref={sectionRef} className="py-20 px-6 bg-slate-50">
            <div className="max-w-container mx-auto">
                <motion.div
                    initial={{ opacity: 0 }}
                    whileInView={{ opacity: 1 }}
                    viewport={{ once: true }}
                    className="mb-12"
                >
                    <h2 className="text-4xl md:text-5xl font-bold mb-4 text-slate-900">
                        <span className="text-accent font-mono text-xl">01.</span> About Me
                    </h2>
                    <div className="h-px bg-slate-200 w-full"></div>
                </motion.div>

                <div className="grid md:grid-cols-2 gap-12">
                    <div className="animate-on-scroll">
                        <h3 className="text-2xl font-bold text-slate-800 mb-4">Profile</h3>
                        <p className="text-slate-600 leading-relaxed mb-6">
                            Organized, self-driven, and tech-savvy professional with a strong background in software development and UI/UX design.
                            Proven ability to work in dynamic environments, with a keen eye for detail and a commitment to high-quality work.
                        </p>
                        <p className="text-slate-600 leading-relaxed">
                            Seeking opportunities as a <span className="text-accent font-semibold">Frontend Developer</span> to leverage my critical thinking,
                            problem-solving skills, and collaborative experience in supporting high-end projects.
                        </p>
                    </div>

                    <div className="animate-on-scroll">
                        <h3 className="text-2xl font-bold text-slate-800 mb-4">Soft Skills</h3>
                        <div className="grid grid-cols-2 gap-3">
                            {softSkills.map((skill, index) => (
                                <motion.div
                                    key={skill}
                                    initial={{ opacity: 0, scale: 0.8 }}
                                    whileInView={{ opacity: 1, scale: 1 }}
                                    viewport={{ once: true }}
                                    transition={{ delay: index * 0.05 }}
                                    whileHover={{ scale: 1.05, x: 5 }}
                                    className="flex items-center gap-2 text-slate-600"
                                >
                                    <span className="text-accent">▹</span>
                                    <span>{skill}</span>
                                </motion.div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default About;
